// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 depositAmount, address actor) public {
        vm.assume(depositAmount > 0);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();
        uint balanceBefore = address(c).balance;
        vm.prank(actor);
        c.withdrawAll();
        uint balanceAfter = address(c).balance;
        assertTrue(balanceAfter < balanceBefore);
    }
}
